// "trail \"Add foo\"".
func describeTrailRef(t *api.TrailResource) string {
	title := strings.TrimSpace(t.Title)
	if t.Number > 0 {
		if title == "" {
			return fmt.Sprintf("trail #%d", t.Number)
		}
		return fmt.Sprintf("trail #%d (%s)", t.Number, title)
	}
	if title == "" {
		return "trail"
	}
	return fmt.Sprintf("trail %q", title)
